import backtrader as bt


class IntraRangeMomentumTripleBarriers(bt.Strategy):
    def __init__(self):
        self.sma = bt.indicators.SMA(self.data.close, period=20)
        self.stochastic = bt.indicators.Stochastic(
            self.data,
            period=14,
            period_dfast=3,
            period_dslow=3,
        )
        self.bollinger = bt.indicators.BollingerBands(
            self.data.close,
            period=20,
            devfactor=2,
        )
        self.atr = bt.indicators.ATR(self.data, period=14)
        self.stochastic_cross = bt.indicators.CrossOver(
            self.stochastic.percK,
            self.stochastic.percD,
        )
        self.sma_cross = bt.indicators.CrossOver(self.data.close, self.sma)

        self.order = None
        self.entry_bar = None

        self.broker.setcommission(commission=0.0002)
        self.broker.set_slippage_perc(perc=0.001)

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.isbuy() and self.position.size > 0:
                self.entry_bar = len(self)
            elif order.issell() and self.position.size < 0:
                self.entry_bar = len(self)
            elif not self.position:
                self.entry_bar = None
            self.order = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            self.order = None

    def next(self):
        if self.order:
            return

        close = self.data.close[0]

        if self.position.size > 0:
            if (
                self.data.high[0] >= self.bollinger.top[0]
                or self.data.low[0] <= self.bollinger.bot[0]
                or self.sma_cross[0] < 0
                or len(self) - self.entry_bar >= 20
            ):
                self.order = self.close()
            return

        if self.position.size < 0:
            if (
                self.data.low[0] <= self.bollinger.bot[0]
                or self.data.high[0] >= self.bollinger.top[0]
                or self.sma_cross[0] > 0
                or len(self) - self.entry_bar >= 20
            ):
                self.order = self.close()
            return

        daily_range_ratio = (self.data.high[0] - self.data.low[0]) / close
        atr_ratio = self.atr[0] / close

        if daily_range_ratio < 0.002 or atr_ratio <= 0.0015:
            return

        size = (self.broker.getvalue() * 0.01) / close

        if (
            close > self.sma[0]
            and self.stochastic.percK[0] > 66
            and self.stochastic_cross[0] > 0
        ):
            self.order = self.buy(size=size)
        elif (
            close < self.sma[0]
            and self.stochastic.percK[0] < 33
            and self.stochastic_cross[0] < 0
        ):
            self.order = self.sell(size=size)
